package com.example.smartexpenseanalyzer.service;
import com.example.smartexpenseanalyzer.model.*; import com.example.smartexpenseanalyzer.repository.AdminProfileRepository; import org.springframework.stereotype.Service; import java.util.*; import java.math.*;
@Service public class AdminProfileService { private final AppUserDetailsService users; private final ExpenseService expenses; private final AdminProfileRepository profiles; public AdminProfileService(AppUserDetailsService users,ExpenseService expenses,AdminProfileRepository profiles){this.users=users;this.expenses=expenses;this.profiles=profiles;} private Map<String,Object> safe(AppUser u){return Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role,"budget",u.budget);} public void ensureProfile(AppUser user){if(user.role.equals("ADMIN")&&profiles.findByAppUser(user).isEmpty())profiles.save(new AdminProfile(user));} public AppUser updateRole(Long id,String role){AppUser user=users.find(id).orElseThrow();user.role=role;user=users.save(user);if(role.equals("ADMIN"))ensureProfile(user);else profiles.findByAppUser(user).ifPresent(profiles::delete);return user;} public void removeProfile(Long id){users.find(id).flatMap(profiles::findByAppUser).ifPresent(profiles::delete);} public Map<String,Object> overview(){List<AppUser> us=users.all();List<Expense> es=expenses.all();Map<String,Object> out=new LinkedHashMap<>();out.put("users",us.size());out.put("expenses",es.size());out.put("total",es.stream().map(e->e.amount).reduce(BigDecimal.ZERO,BigDecimal::add));out.put("members",us.stream().map(this::safe).toList());out.put("latest",es.stream().limit(20).map(e->Map.<String,Object>of("owner",e.user.name,"email",e.user.email,"description",e.description,"category",e.category,"amount",e.amount,"date",e.date)).toList());return out;} }
